window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-7441dbcd0ab0c46f"]={"versions": [{"id": "FIG-7441dbcd0ab0c46f", "releases": ["R2.1.20"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Strukturelles Hardware-Topologie- und Modellierungsdiagramm des AUTOSAR ECU Resource Templates (AUTOSAR_ResourceTemplateECU). Das Diagramm veranschaulicht die Verschaltungsebene innerhalb eines Hardware-Containers und die Zuordnungsregeln zwischen Hardware-Verbindungen (<code>HW Connection</code>) und Hardware-Ports (<code>HW Port</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>HW Container</strong>: Übergeordnete Begrenzungseinheit / Kapselung für die enthaltenen Hardware-Elemente und deren interne Verschaltung.\n</li><li><strong>HW Element 1</strong>: Hardware-Element mit drei definierten Ports an der rechten Kante; der mittlere Port ist an die Verbindung <code>Conn1</code> angebunden, die beiden äußeren Ports sind unbeschaltet dargestellt.\n</li><li><strong>HW Element 2</strong>: Hardware-Element mit einem Port an der linken Kante, angebunden an <code>Conn1</code>.\n</li><li><strong>HW Element 3</strong>: Hardware-Element mit einem Port an der linken Kante, angebunden an <code>Conn1</code>.\n</li><li><strong>HW Connection (<code>Conn1</code>)</strong>: Verzweigte Hardware-Verbindung, die den mittleren Port von <code>HW Element 1</code> mit den jeweiligen Ports von <code>HW Element 2</code> und <code>HW Element 3</code> als 1-zu-Mehrpunkt-Topologie verbindet.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Strukturmodell ohne zeitlichen Ablauf oder Zustandsübergänge. Die Darstellung definiert die zulässige statische Konfiguration einer Punkt-zu-Mehrpunkt-Topologie, bei der ein einzelner Hardware-Verbindungspfad (<code>Conn1</code>) mehrere Hardware-Ports gleichzeitig elektrisch bzw. logisch koppelt.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Veranschaulichung der Metamodell-Regel für das ECU Resource Template: Eine Hardware-Verbindung (<code>HW Connection</code>) darf mehreren Hardware-Ports zugeordnet werden (1:n- bzw. n-Port-Zuordnung an einer Verbindung). Bei der Modellierung und Validierung von Hardware-Topologien ist sicherzustellen, dass Port-Kopplungen über verzweigte <code>HW Connection</code>-Elemente modellkonform unterstützt werden.</p>"}, {"id": "FIG-cdf5bdac8f2270bb", "releases": ["R3.0.7", "R3.1.5", "R3.2.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Strukturelles Hardware-Topologie- und Modellierungsdiagramm des AUTOSAR ECU Resource Templates (AUTOSAR_ResourceTemplateECU). Das Diagramm veranschaulicht die Verschaltungsebene innerhalb eines Hardware-Containers und die Zuordnungsregeln zwischen Hardware-Verbindungen (<code>HW Connection</code>) und Hardware-Ports (<code>HW Port</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>HW Container</strong>: Übergeordnete Begrenzungseinheit / Kapselung für die enthaltenen Hardware-Elemente und deren interne Verschaltung.\n</li><li><strong>HW Element 1</strong>: Hardware-Element mit drei definierten Ports an der rechten Kante; der mittlere Port ist an die Verbindung <code>Conn1</code> angebunden, die beiden äußeren Ports sind unbeschaltet dargestellt.\n</li><li><strong>HW Element 2</strong>: Hardware-Element mit einem Port an der linken Kante, angebunden an <code>Conn1</code>.\n</li><li><strong>HW Element 3</strong>: Hardware-Element mit einem Port an der linken Kante, angebunden an <code>Conn1</code>.\n</li><li><strong>HW Connection (<code>Conn1</code>)</strong>: Verzweigte Hardware-Verbindung, die den mittleren Port von <code>HW Element 1</code> mit den jeweiligen Ports von <code>HW Element 2</code> und <code>HW Element 3</code> als 1-zu-Mehrpunkt-Topologie verbindet.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Strukturmodell ohne zeitlichen Ablauf oder Zustandsübergänge. Die Darstellung definiert die zulässige statische Konfiguration einer Punkt-zu-Mehrpunkt-Topologie, bei der ein einzelner Hardware-Verbindungspfad (<code>Conn1</code>) mehrere Hardware-Ports gleichzeitig elektrisch bzw. logisch koppelt.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Veranschaulichung der Metamodell-Regel für das ECU Resource Template: Eine Hardware-Verbindung (<code>HW Connection</code>) darf mehreren Hardware-Ports zugeordnet werden (1:n- bzw. n-Port-Zuordnung an einer Verbindung). Bei der Modellierung und Validierung von Hardware-Topologien ist sicherzustellen, dass Port-Kopplungen über verzweigte <code>HW Connection</code>-Elemente modellkonform unterstützt werden.</p>"}], "trans": [{"from": "FIG-7441dbcd0ab0c46f", "to": "FIG-cdf5bdac8f2270bb", "fr": "R2.1.20", "tr": "R3.0.7", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
